            <div className={utilities("spec-table-label", [2703, "[:where(&).spec-table-label]:[padding:18px_24px] [:where(&).spec-table-label]:font-semibold [:where(&).spec-table-label]:[font-size:14px] [:where(&).spec-table-label]:[color:#1e293b] [:where(&).spec-table-label]:[line-height:1.6]"], [2710, "[@media_(max-width:_640px)]:[:where(&).spec-table-label]:[padding:14px_16px_4px] [@media_(max-width:_640px)]:[:where(&).spec-table-label]:[font-size:13px]"])}>{item.label}</div>
